function parseProposed(s){const str=String(s||'');const mm=str.match(/(\d+)\s+(\S+)\s+(\d{4})\s*-\s*(\d+):(\d+)\s*(ص|م)/);if(!mm)return null;let h=+mm[4];const min=+mm[5];if(mm[6]==='م'&&h<12)h+=12;if(mm[6]==='ص'&&h===12)h=0;const mon=AR_MONTHS.indexOf(mm[2]);const rest=str.slice(mm.index+mm[0].length);const em=rest.match(/(\d+):(\d+)\s*(ص|م)/);let eh,emin,hasEnd=false;if(em){hasEnd=true;eh=+em[1];emin=+em[2];if(em[3]==='م'&&eh<12)eh+=12;if(em[3]==='ص'&&eh===12)eh=0;}else{eh=h+1;emin=min;}return {y:+mm[3],m:mon,d:+mm[1],h,min,endH:eh,endMin:emin,hasEnd,key:(+mm[3])+'-'+String(mon+1).padStart(2,'0')+'-'+String(+mm[1]).padStart(2,'0')};}
function ymdKey(dt){return dt.getFullYear()+'-'+String(dt.getMonth()+1).padStart(2,'0')+'-'+String(dt.getDate()).padStart(2,'0');}
function timeLabel(h,min){const ap=h<12?'ص':'م';let hh=h%12;if(hh===0)hh=12;return hh+':'+String(min).padStart(2,'0')+' '+ap;}
function timeRange(p){if(!p)return '';return timeLabel(p.h,p.min)+' – '+timeLabel(p.endH,p.endMin);}
