DCDD.install=function(self){
  self._ddDoc=function(e){ if(self.state.openDD && !(e.target.closest&&e.target.closest('[data-dd],[data-dd-pop]'))) self.setState({openDD:null,ddRect:null}); };
  document.addEventListener('mousedown',self._ddDoc,true);
  self._ddScroll=function(){ if(self.state.openDD) self.setState({openDD:null,ddRect:null}); };
  window.addEventListener('scroll',self._ddScroll,true);
};
DCDD.uninstall=function(self){
  if(self._ddDoc) document.removeEventListener('mousedown',self._ddDoc,true);
  if(self._ddScroll) window.removeEventListener('scroll',self._ddScroll,true);
};

/* ---- generic Arabic-date parser (shared; was previously inline in otasks) ---- */
var AR_MON_IDX={'يناير':0,'فبراير':1,'مارس':2,'أبريل':3,'مايو':4,'يونيو':5,'يوليو':6,'أغسطس':7,'سبتمبر':8,'أكتوبر':9,'نوفمبر':10,'ديسمبر':11};
function parseAr(s){if(!s)return null;const m=String(s).trim().split(/\s+/);if(m.length<3)return null;const d=parseInt(m[0],10);const mo=AR_MON_IDX[m[1]];const y=parseInt(m[2],10);if(isNaN(d)||mo==null||isNaN(y))return null;return new Date(y,mo,d);}
